package com.bank.protocol;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.logging.Logger;

public class MessageFramer {

    private static final Logger log = Logger.getLogger(MessageFramer.class.getName());

    public int longestValid(String s) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(-1);                                // sentinel base position
        int best = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                stack.push(i);                         // remember open index
            } else {
                stack.pop();                           // match an open
                if (stack.isEmpty()) {
                    stack.push(i);                     // unmatched ')' becomes new base
                } else {
                    best = Math.max(best, i - stack.peek()); // length of current run
                }
            }
        }
        final int result = best;
        log.info(() -> "Longest valid parentheses = " + result);
        return result;
    }
}
