package com.bank.protocol;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class ValidParensDemo {

    private static final Logger log = Logger.getLogger(ValidParensDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Message Framer (Longest Valid Parentheses)");
        MessageFramer framer = new MessageFramer();
        log.info("')()())' → " + framer.longestValid(")()())")); // 4
        log.info("'(()' → " + framer.longestValid("(()"));          // 2
    }
}
